using TerraRuntime.Core.Worlds;
using System.IO.Compression;using System.Text.Json;using TerraRuntime.Core;using TerraRuntime.Core.Npcs;using TerraRuntime.Core.Projectiles;using TerraRuntime.Core.Worlds.Generation;using TerraRuntime.Gameplay.Npcs;using TerraRuntime.World;
namespace TerraRuntime.Tests;
public sealed class GenerationDungeonDebrisCaller1458Tests {
 [Fact]
 public void Actual_medium_Dungeon_caller_retains_two_source_debris_births(){
  using var raw=typeof(GenerationDungeonDebrisCaller1458Tests).Assembly.GetManifestResourceStream("GenerationDungeonDebrisMedium1458")!;using var gzip=new GZipStream(raw,CompressionMode.Decompress);using var expected=JsonDocument.Parse(gzip);var world=new Workspace(6400,1800);Assert.True(world.TileStore.TryAttachTileEntities([],1000));var npcs=new RuntimeNpcStore();var projectiles=new RuntimeProjectileStore();npcs.SetVanillaSpawnContextSource(()=>new VanillaNpcSpawnContext(1,0,false){WorldDifficulty=1});npcs.SetVanillaSpawnWetCollisionSource((x,y,w,h)=>VanillaWorldCollision.GetLiquidContacts(world.TileStore,x,y,w,h).Wet);world.AttachEntityEffects(new WorldGenerationEntityEffects1458(npcs,projectiles,true),0,1);
  using var cancellation=CancellationTokenSource.CreateLinkedTokenSource(TestContext.Current.CancellationToken);var observer=new Observer(world,projectiles,cancellation,expected.RootElement);var request=new WorldGenerationRequest(Provider1458.GeneratorId,"MediumDungeonSource",1458,6400,1800){SeedText="1458",Options=new(WorldGenerationGameMode.Classic,WorldGenerationEvil.Crimson)};var result=RuntimeWorldGenerationExecutor.Execute(new Provider(new SourceBackedFinal1458(),observer),request,world,null,cancellation.Token);Assert.True(result.Error is null,result.Error?.ToString());Assert.Equal("Cancelled",result.Status.ToString());Assert.True(observer.Seen);
 }
 private sealed class Provider(IWorldGenerationProvider inner,Observer observer):IWorldGenerationProvider {public WorldGeneratorId Id=>inner.Id;public void BuildPlan(in WorldGenerationRequest request,IWorldGenerationPlanBuilder builder)=>inner.BuildPlan(in request,new Builder(builder,observer));}
 private sealed class Builder(IWorldGenerationPlanBuilder inner,Observer observer):IWorldGenerationPlanBuilder {public void Add(WorldGenerationPassDescriptor descriptor,IWorldGenerationPass pass)=>inner.Add(descriptor,new Pass(descriptor,pass,observer));}
 private sealed class Pass(WorldGenerationPassDescriptor descriptor,IWorldGenerationPass inner,Observer observer):IWorldGenerationPass {public void Execute(IWorldGenerationContext context){inner.Execute(context);observer.After(descriptor,context);}}
 private sealed class Observer(Workspace world,RuntimeProjectileStore projectiles,CancellationTokenSource cancellation,JsonElement expected){public bool Seen;public void After(WorldGenerationPassDescriptor descriptor,IWorldGenerationContext context){
  if(descriptor.Id.Value.Split('/')[^1]!="Dungeon")return;Seen=true;Assert.Equal(expected.GetProperty("grid").GetString(),GenerationNaturalPrefix49Tests.GridHash(world));Assert.Equal(expected.GetProperty("rngHash").GetString(),GenerationNaturalPrefix49Tests.RandomHash(context.VanillaRandom!,includeReport:false));Assert.Equal(expected.GetProperty("solidity").EnumerateArray().Select(a=>a.GetBoolean()),Enumerable.Range(0,754).Select(i=>world.IsVanillaGenerationSolid(new((ushort)i))));var rows=expected.GetProperty("projectiles");Assert.Equal(rows.GetArrayLength(),projectiles.ActiveCount);foreach(var e in rows.EnumerateArray()){Assert.True(projectiles.TryGetActive(e.GetProperty("slot").GetUInt16(),out var actual));Assert.True(projectiles.TryGetLifecycle(actual.Handle,out var life));Assert.Equal(e.GetProperty("type").GetInt32(),actual.Type.Value);Assert.Equal(e.GetProperty("owner").GetInt32(),actual.Spawner);Assert.Equal(e.GetProperty("x").GetSingle(),actual.PositionX);Assert.Equal(e.GetProperty("y").GetSingle(),actual.PositionY);Assert.Equal(e.GetProperty("vx").GetSingle(),actual.VelocityX);Assert.Equal(e.GetProperty("vy").GetSingle(),actual.VelocityY);Assert.Equal(e.GetProperty("timeLeft").GetInt32(),life.TimeLeft);Assert.Equal(e.GetProperty("damage").GetInt32(),actual.Damage);Assert.Equal(e.GetProperty("originalDamage").GetInt32(),actual.OriginalDamage);Assert.Equal(e.GetProperty("knockBack").GetSingle(),actual.KnockBack);Assert.True(life.SourceNetUpdate);Assert.Equal(e.GetProperty("ai").EnumerateArray().Select(a=>a.GetSingle()).ToArray(),new[]{actual.Ai.Ai0,actual.Ai.Ai1,actual.Ai.Ai2});}cancellation.Cancel();
 }}
}
